    }

    console.log('AI Teammate Token Usage Reporter — ' + custom.workspace + '/' + custom.repository + ' [' + custom.workflowId + ']');
    var runs = listCompletedRuns(custom);
    console.log('Found ' + runs.length + ' completed workflow run(s)');

