}

function extractTokenUsage(logs) {
    var lines = String(logs || '').split(/\r?\n/);
    var lastRequests = null;
    var samples = [];
    var seenFaSegments = {};
    var resumeDetected = false;
    var resumeStages = [];
    var feedbackLoopCount = 0;
    var rateLimitRetryCount = 0;
    var rateLimitDetected = false;
    var timeoutCount = 0;

