Current:
```js
function sleepMilliseconds(ms) {
  ms = parseInt(ms, 10) || 0;
  if (ms <= 0) return;
  if (typeof Java !== 'undefined' && Java.type) {
      Java.type('java.lang.Thread').sleep(ms);
      return;
